// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 initialMinSum, uint256 newMinSum) internal {
        vm.assume(true);
        try c.Initialized() {} catch { return; }
        try c.SetMinSum(initialMinSum) {} catch { return; }
        try c.SetMinSum(newMinSum) {} catch { return; }
        assertTrue(c.MinSum() == initialMinSum);
    }

    function testFuzz_run(uint256 initialMinSum, uint256 newMinSum) public {
        _run(initialMinSum, newMinSum);
    }

    receive() external payable {}
}
